ALTER TABLE "adoption" ADD FOREIGN KEY ("cleaning_id") REFERENCES "cleaning" ("id") ;

ALTER TABLE "management_log" ADD FOREIGN KEY ("adoption_id") REFERENCES "adoption" ("id") ;

ALTER TABLE "management_log" ADD FOREIGN KEY ("request_id") REFERENCES "inspection_request" ("id") ;

ALTER TABLE "management_log" ADD FOREIGN KEY ("reviewed_by") REFERENCES "users" ("id") ;

ALTER TABLE "cleaning" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ;

ALTER TABLE "cleaning" ADD FOREIGN KEY ("drain_id") REFERENCES "drain" ("id") ;

ALTER TABLE "cleaning" ADD FOREIGN KEY ("request_id") REFERENCES "inspection_request" ("id") ;

ALTER TABLE "cleaning" ADD FOREIGN KEY ("reviewed_by") REFERENCES "users" ("id") ;

ALTER TABLE "ai_verification" ADD FOREIGN KEY ("cleaning_id") REFERENCES "cleaning" ("id") ;

ALTER TABLE "ai_verification" ADD FOREIGN KEY ("management_log_id") REFERENCES "management_log" ("id") ;

ALTER TABLE "tool_rental" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ;

ALTER TABLE "tool_rental" ADD FOREIGN KEY ("tool_box_id") REFERENCES "tool_box" ("id") ;

ALTER TABLE "inspection_request" ADD FOREIGN KEY ("forecast_id") REFERENCES "rain_forecast" ("id") ;

ALTER TABLE "inspection_request" ADD FOREIGN KEY ("drain_id") REFERENCES "drain" ("id") ;

ALTER TABLE "inspection_request" ADD FOREIGN KEY ("adoption_id") REFERENCES "adoption" ("id") ;

ALTER TABLE "inspection_request" ADD FOREIGN KEY ("substitute_user_id") REFERENCES "users" ("id") ;

ALTER TABLE "report" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ;

ALTER TABLE "report" ADD FOREIGN KEY ("drain_id") REFERENCES "drain" ("id") ;

ALTER TABLE "report" ADD FOREIGN KEY ("processed_by") REFERENCES "users" ("id") ;

