ALTER TABLE "notification" ADD FOREIGN KEY ("request_id") REFERENCES "inspection_request" ("id") ;

ALTER TABLE "notification" ADD FOREIGN KEY ("adoption_id") REFERENCES "adoption" ("id") ;

-- ───────── ERD 밖 제약 (부분 인덱스 · CHECK) ─────────
-- 배수구당 진행 중인 입양 1개
CREATE UNIQUE INDEX uq_adoption_active_drain ON "adoption" ("drain_id") WHERE "status" = 'ACTIVE' AND "deleted_at" IS NULL;
-- 1인 1개 대여
CREATE UNIQUE INDEX uq_tool_rental_active_user ON "tool_rental" ("user_id") WHERE "status" = 'RENTED' AND "deleted_at" IS NULL;
-- 더러움 단계 1~3
ALTER TABLE "drain" ADD CONSTRAINT ck_drain_dirt_level CHECK ("dirt_level" BETWEEN 1 AND 3);
-- 도구함 수량은 0 ~ total
ALTER TABLE "tool_box" ADD CONSTRAINT ck_tool_box_count CHECK ("available_count" BETWEEN 0 AND "total_count");
-- 비 예보 점검이면 request_id 필수, 정기 점검이면 없음
ALTER TABLE "management_log" ADD CONSTRAINT ck_management_log_type CHECK (("type" = 'RAIN') = ("request_id" IS NOT NULL));
-- AI 인증은 청소 또는 관리 기록 중 하나에만 붙는다
ALTER TABLE "ai_verification" ADD CONSTRAINT ck_ai_verification_target CHECK (num_nonnulls("cleaning_id", "management_log_id") = 1);

-- ───────── 조회용 인덱스 ─────────
CREATE INDEX idx_drain_location ON "drain" ("latitude", "longitude");
CREATE INDEX idx_notification_user_read ON "notification" ("user_id", "read_at");
CREATE INDEX idx_inspection_request_status ON "inspection_request" ("status");
CREATE INDEX idx_adoption_user_status ON "adoption" ("user_id", "status");
